/**
 * THE DERIVED CENSUS IS CURRENT — regenerating `w3-verdicts.ndjson` must change nothing.
 *
 * ⛔⛔ THE DEFECT THIS EXISTS FOR, RECORDED AND UNFIXED UNTIL NOW (`REG-F-367`). The artifact is generated by
 * `scripts/tracker/measure.ts --write` and COMMITTED. Regenerating it during an unrelated slice moved **25
 * items** — `CreateContextAssemblyPolicy` and `RecordModelExchange` were absent entirely — so it had drifted
 * silently across several commits, and was only regenerated because a DIFFERENT gate went red for a DIFFERENT
 * reason. Counts were being quoted from it while it was wrong.
 *
 * ── ⚠ AND `tracker:check` ALREADY EXISTED AND DID NOT CATCH IT, WHICH IS THE INTERESTING PART ────────────────
 * That script has three named refusals — `DB_MISSING`, `SOURCE_STALE`, `DIGEST_MISMATCH` — and every one of them
 * compares the INDEX against the CENSUS FILES. `SOURCE_STALE` hashes tracked *documents*. Nothing anywhere
 * compared the census against the CODE it measures, so the index agreed perfectly with a stale census and
 * reported `ok:true` for a week. ⭑ A check whose population excludes the thing that drifts is not a weak check;
 * it is a check of something else.
 *
 * ── ⭑ WHY A STRICT "REGENERATION IS A NO-OP" RATCHET IS AFFORDABLE HERE, MEASURED BEFORE IT WAS BUILT ────────
 * The measurement keys on `packages/rph-domain/src/enforcement-register.ts` — the CODE — and NOT on the prose
 * register, so ordinary register appends do not move it. Driven: two entries were appended the day this was
 * written and the census did not move. What moves it is a disposition changing, a command appearing, or a
 * consumer walk finding a name it did not find before — each of which is a verdict genuinely changing, which is
 * exactly when a derived artifact should be rewritten. The remedy is one command, named in the failure.
 *
 * ── ⛔ THE INSTRUMENT MUST NOT FAIL LIKE ITS SUBJECT, AND IT CAN ────────────────────────────────────────────
 * `measure.ts` READS the census directory, including its own output, and REFUSES a record it cannot parse:
 * corrupting one verdict makes it exit 1 with `tracker: … unknown verdict` and print NOTHING. An empty
 * measurement compared against a 343-line file is a red — but a red whose stated reason would be "343 records
 * went missing", which is false and would send a reader to the wrong place. So the spawn's success is asserted
 * SEPARATELY and first. ⭑ Driven both ways while writing this: dropping five records from the committed file
 * left the measurement at 343 and exit 0 (the generator is pure with respect to its own output), while
 * corrupting one record collapsed it to 0 and exit 1.
 */
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..');
const COMMITTED = 'docs/tracking/census/w3-verdicts.ndjson';
const REMEDY = 'bun scripts/tracker/measure.ts --write';

/** Non-empty lines, line-ending agnostic — the file is LF and a spawn on Windows may not be. */
function records(text: string): string[] {
	return text.split(/\r?\n/).filter((l) => l.trim() !== '');
}

export interface CensusDrift {
	readonly onlyFresh: string[];
	readonly onlyCommitted: string[];
}

/**
 * What a regeneration would change, as whole records.
 *
 * ⚠ SET DIFFERENCE, NOT A POSITIONAL DIFF. Both sides are emitted sorted by a stable key, but a positional
 * comparison reports one inserted record as every subsequent line differing — a true red that names 300 innocent
 * items and buries the two that moved. The failure has to be readable or it will be re-run until green.
 */
export function censusDrift(fresh: readonly string[], committed: readonly string[]): CensusDrift {
	const f = new Set(fresh);
	const c = new Set(committed);
	return {
		onlyFresh: fresh.filter((l) => !c.has(l)),
		onlyCommitted: committed.filter((l) => !f.has(l))
	};
}

/** `item_id` out of a record, for a failure message a human can act on. */
export function itemOf(record: string): string {
	try {
		return String((JSON.parse(record) as { item_id?: unknown }).item_id ?? '?');
	} catch {
		return '<unparseable>';
	}
}

// ⚠ NO `shell: true`. The sibling substrate witness spawns `bun` directly and this follows it — a shell
// spawn with an argument array is deprecated in Node and concatenates rather than escapes, and a gate that
// emits a deprecation warning on every run teaches its reader to ignore its output.
const measured = spawnSync('bun', [join(REPO, 'scripts', 'tracker', 'measure.ts')], {
	cwd: REPO,
	encoding: 'utf8',
	timeout: 120_000
});
const FRESH = records(measured.stdout ?? '');
const COMMITTED_RECORDS = records(readFileSync(join(REPO, COMMITTED), 'utf8'));

describe('the derived W-3 census is current', () => {
	it('⭑⭑ CONTROL — the MEASUREMENT SUCCEEDED, asserted before anything is called stale', () => {
		// ⛔ THIS IS THE LIMB THAT STOPS THE INSTRUMENT FAILING LIKE ITS SUBJECT. `measure.ts` refuses a census
		// record it cannot parse and exits 1 printing nothing; without this assertion that empty output would be
		// reported below as "every record has gone missing" — a red with a false reason, which is worse than a
		// green because it sends the reader somewhere else. DRIVEN: corrupting one verdict value produces exactly
		// this state.
		expect(measured.status, `\`${REMEDY}\` failed:\n${measured.stderr ?? ''}`).toBe(0);
		expect(FRESH.length, 'the measurement produced no records at all').toBeGreaterThan(200);
	});

	it('⭑ CONTROL — the committed artifact is a real population, not an empty file', () => {
		// Without this, deleting the file's contents and regenerating nothing would compare empty to empty on the
		// day the measurement also broke. Two empties agreeing is the shape this repository has already recorded.
		expect(COMMITTED_RECORDS.length, `${COMMITTED} is empty or missing`).toBeGreaterThan(200);
	});

	it('⛔⛔ regenerating the census changes NOTHING — it is derived, and it is committed', () => {
		// THE MUTANT: drop or edit any record in the committed file. DRIVEN — dropping five reddens this and
		// leaves the two controls above green, which is the separation that makes the failure legible.
		const drift = censusDrift(FRESH, COMMITTED_RECORDS);
		const moved = [...new Set([...drift.onlyFresh, ...drift.onlyCommitted].map(itemOf))].sort();
		expect(
			moved,
			`the committed census disagrees with a fresh measurement of this tree — ${drift.onlyFresh.length} ` +
				`record(s) the tree now yields are absent from it, and ${drift.onlyCommitted.length} it holds are no ` +
				`longer produced. This artifact is DERIVED: regenerate it in the same commit as the change that ` +
				`moved it, with \`${REMEDY}\`. Counts quoted from a stale census are wrong, which is REG-F-367.`
		).toEqual([]);
	});
});

describe('REG-F-383 — the census does not quote running totals it is not about', () => {
	it('⛔ no evidence string embeds a raw source count', () => {
		// ⭑⭑ THE DEFECT THIS CLOSES, OBSERVED FOUR TIMES IN ONE DAY. The absence evidence used to read *"'X' not
		// found in 487 production or 525 test sources"*, so ADDING ONE TEST FILE ANYWHERE rewrote fifteen records
		// of this committed, derived artifact — with EVERY VERDICT UNCHANGED. Three separate increments had to
		// regenerate it for changes none of its records were about.
		//
		// ⛔ AND THE COUNTS WERE NEVER THE NON-VACUITY EVIDENCE. `measure.ts` GATES the emission on its positive
		// control: a search whose control does not fire emits `SEARCH INVALID … no absence claims emitted`
		// instead of a verdict. The control is the guarantee, structurally. The integers only made the artifact
		// churn on changes it is not about.
		//
		// ⚠ THE RULE IS NARROW ON PURPOSE: a count of the SEARCHED POPULATION is what churns, because it moves
		// whenever the repository does. A count that is itself the finding is not what this forbids.
		const offenders = COMMITTED_RECORDS.filter((record) =>
			/\d+\s+(production|test)\s+sources?\b/.test(JSON.stringify(record))
		).map((record) => (record as { item_id?: string }).item_id ?? '(unnamed)');
		expect(
			offenders,
			'this record quotes the size of the population it searched, so it is rewritten every time the ' +
				'repository grows a file — a derived artifact must move when its VERDICT moves and not before'
		).toEqual([]);
	});

	it('⭑ CONTROL — the census is non-empty and its absence evidence is still present', () => {
		// Without this, deleting every absence record would satisfy the limb above. The population floor and the
		// evidence probe together mean "no totals" cannot be achieved by having no evidence to check.
		expect(
			COMMITTED_RECORDS.length,
			'the census is empty — the reader or the file broke'
		).toBeGreaterThan(100);
		const absence = COMMITTED_RECORDS.filter((record) =>
			/not found in any production or test source/.test(JSON.stringify(record))
		);
		expect(absence.length, 'no absence evidence remains to check').toBeGreaterThanOrEqual(10);
	});
});

describe('the drift reader is exercised against inputs whose answer is known', () => {
	// ⚠ A CENSUS INSTRUMENT THAT UNDERCOUNTS SILENTLY IS WORSE THAN NO INSTRUMENT — this repository's own
	// recurring lesson, and the reason the comparison is a tested function rather than an inline `toEqual`.
	const rec = (id: string, v: string) => JSON.stringify({ type: 'verdict', item_id: id, verdict: v });

	it('reports nothing when the two agree', () => {
		const a = [rec('X', 'TESTED'), rec('Y', 'DECLARED')];
		expect(censusDrift(a, [...a])).toEqual({ onlyFresh: [], onlyCommitted: [] });
	});

	it('⭑ agrees regardless of ORDER — a reordering is not a drift', () => {
		const a = [rec('X', 'TESTED'), rec('Y', 'DECLARED')];
		expect(censusDrift(a, [a[1]!, a[0]!])).toEqual({ onlyFresh: [], onlyCommitted: [] });
	});

	it('names a record the tree now yields that the file lacks — the absent-entirely case', () => {
		// `CreateContextAssemblyPolicy` and `RecordModelExchange` were in exactly this state for a week.
		const drift = censusDrift([rec('X', 'TESTED'), rec('NEW', 'TESTED')], [rec('X', 'TESTED')]);
		expect(drift.onlyFresh.map(itemOf)).toEqual(['NEW']);
		expect(drift.onlyCommitted).toEqual([]);
	});

	it('names a record the file holds that the tree no longer yields', () => {
		const drift = censusDrift([rec('X', 'TESTED')], [rec('X', 'TESTED'), rec('GONE', 'DECLARED')]);
		expect(drift.onlyCommitted.map(itemOf)).toEqual(['GONE']);
	});

	it('⭑ a CHANGED verdict shows on both sides, because the item moved rather than appeared', () => {
		const drift = censusDrift([rec('X', 'TESTED')], [rec('X', 'DECLARED')]);
		expect(drift.onlyFresh.map(itemOf)).toEqual(['X']);
		expect(drift.onlyCommitted.map(itemOf)).toEqual(['X']);
	});

	it('⭑ CONTROL — the id reader survives an unparseable line instead of throwing', () => {
		// The gate must be able to REPORT a corrupt file, not die building the message for it.
		expect(itemOf('{not json')).toBe('<unparseable>');
	});
});
